  "It closed before it opened. Try again.": "它还没打开就关闭了。请重试。",
  "It couldn’t start on this Mac.": "它无法在这台 Mac 上启动。",
  "It ended before it could write up the build.": "在写出构建总结前就结束了。",
  "It finishes its own setup the first time it opens.": "首次打开时，它会自己完成设置。",
  "It hasn't started yet.": "还没有开始。",
  "It installs when you relaunch; Genex tells you when it's ready.": "重新启动时会自动安装；准备好后 Genex 会通知你。",
  "It is on and stays on: its new code runs as soon as it loads, and each of its tools asks you again before it runs.":
    "它已启用并保持启用：新代码一加载就会运行，它的每个工具在运行前都会再次询问你。",
  "It isn’t on this Mac any more. Install it again.": "它已不在这台 Mac 上。请重新安装。",
  "It keeps downloading if you go back.": "返回后仍会继续下载。",
  "It keeps your scripts as files in this game's folder and tells Genex which Studio is this game's.":
    "它把你的脚本作为文件保存在这个游戏的文件夹里，并告诉 Genex 哪个 Studio 属于这个游戏。",
  "It kept getting this wrong, so it stopped to save your credits.": "这里一直出错，为了节省你的积分已停止。",
  "It leaves Play and genex.games and goes back to drafts. The direct link still works, and plays and likes stay if it’s published again.":
    "它会从“游玩”和 genex.games 下架，回到草稿。直接链接仍然有效，重新发布后游玩次数和点赞都会保留。",
  "It may need the setup scripts its packages came with, which didn’t run.":
    "它可能需要依赖包自带的安装脚本，这些脚本没有运行。",
  "It merged this part's work without a reviewer's verdict. The reviewers score parts that build in steps; this one was built in one session.":
    "它未经审查员评判就合并了这个部分的成果。审查员只给分步骤制作的部分打分；这个部分是在一个会话中完成的。",
  "It merges into your build when the lead integrates this part.": "主智能体整合这个部分时，它会合入你的构建。",
  "It needs macOS {version} or later.": "需要 macOS {version} 或更高版本。",
  "It never uses password managers, Windows Settings, password prompts or Genex.":
    "它绝不会使用密码管理器、Windows 设置、密码弹窗或 Genex。",
  "It ran into an error": "遇到了错误",
  "It runs at Genex's moments: {steps}; those steps don't ask you first.":
    "它会在 Genex 的这些时刻运行：{steps}；这些步骤不会事先询问你。",
  "It runs with your access: Genex doesn't sandbox its code.": "它以你的权限运行：Genex 不会把它的代码放进沙盒。",
  "It runs, but no reviewer compared it with the game you had.": "可以运行，但没有审查员把它和你之前的游戏比较过。",
  "It shows up here as soon as it runs.": "游戏一运行就会显示在这里。",
  "It starts off: turn it on in Plugins; each of its tools asks you before it runs.":
    "它默认关闭：请在“插件”中启用；它的每个工具在运行前都会询问你。",
  "It stopped before this was fixed.": "在修好之前就停止了。",
  "It treats this as a {kind} game — that decides the controls it drives before every look, and who reviews it.":
    "它把这当作“{kind}”类游戏——这决定了它每次查看前要操作哪些按键，以及由谁来审查。",
  "It turns on when installed: agents in all your games can use it from your next message.":
    "安装后即开启：从你的下一条消息起，所有游戏中的智能体都能使用它。",
  "It was paused before it could write up the build.": "在写出构建总结前就被暂停了。",
  "It's no longer there.": "它已经不在了。",
  "It's switched on in Studio's settings. Studio answers once a place is open: open one in Studio, or press New Roblox game.":
    "已在 Studio 的设置中开启。打开一个地点后 Studio 才会响应：在 Studio 中打开一个，或点击“新建 Roblox 游戏”。",
  "It's switched on in Studio's settings. Studio answers once it has finished opening.":
    "已在 Studio 的设置中开启。Studio 完全打开后会响应。",
  "Its author no longer shares it.": "作者已不再分享它。",
  "Its code runs on your computer like an app you install. It isn't sandboxed.":
    "它的代码会像你安装的应用一样在你的电脑上运行，不在沙盒中。",
  "Its creator hasn’t shared this game’s project yet, so it can’t be remixed.":
    "作者还没有分享这个游戏的项目，所以暂时不能改编。",
  "Its files are in your game folder, waiting for the lead to use them.":
    "它的文件在你的游戏文件夹中，等待主智能体使用。",
  "Its own scene": "独立场景",
  "Its packages aren’t installed yet — “{install}” runs on one press.": "依赖包还没安装——点一下即可运行“{install}”。",
  "Its packages aren’t installed yet.": "依赖包尚未安装。",
  "Its project didn’t go, so no one can remix it yet.": "项目没有发送成功，所以暂时没人能改编它。",
  "Its project is too big to remix: Genex keeps up to 5 GB and 5,000 files.":
    "项目太大，无法改编：Genex 最多保存 5 GB、5,000 个文件。",
  "Its session failed before it delivered anything.": "它的会话在交付任何内容之前就失败了。",
  "Its source is your own repository: run genex make-remixable in the game’s folder to allow remixing.":
    "它的源码在你自己的仓库里：在游戏文件夹中运行 genex make-remixable 即可允许改编。",
  "Its steps at Genex's moments changed (hooks, observers, locks, folders or harness tools), so it wasn't reloaded: load it again with Load local plugin… to review them":
    "它在 Genex 各个时刻的步骤已更改（钩子、观察器、锁、文件夹或 Harness 工具），因此没有重新加载：请用“加载本地插件…”重新加载以查看",
  "Its time ran out before a final look at your game.": "还没对你的游戏做最后检查，时间就用完了。",
  "Its time ran out before this was fixed.": "还没修好，时间就用完了。",
  "Its tools become available to the agents in your games.": "它的工具会提供给你游戏中的智能体。",
  "Its work is saved, not merged.": "它的工作已保存，但未合入。",
