    "主智能体正在亲自处理下一步；它启动的每个助手都会在这里显示为一行。",
  "The lead saved it after looking at its own captures; no reviewer judged it.":
    "主智能体看过自己的截图后保存了它；没有审查员评判过。",
  "The lead stopped before it said it was done.": "主智能体还没说完成就停止了。",
  "The lead stopped it": "主智能体停止了它",
  "The lead stopped it before the reviewers saw it.": "审查员看到之前，主智能体就停止了它。",
  "The lead stopped the {ordinal}.": "主智能体停止了{ordinal}次尝试。",
  "The lead stopped {count}.": "主智能体停止了其中{count}次。",
