  "The lead's summary": "主智能体的总结",
  "The lead's view of the game": "主智能体眼中的游戏",
  "The lead: done": "主智能体：已完成",
  "The lead: paused": "主智能体：已暂停",
  "The lead: stopped": "主智能体：已停止",
  "The lead: waiting for a worker": "主智能体：正在等待助手",
  "The lead: working on the next step": "主智能体：正在处理下一步",
  "The line you would type in Terminal.": "你会在终端里输入的那一行。",
  "The local folder now contains a different plugin. Load it as a new plugin instead.":
    "本地文件夹中现在是另一个插件。请将它作为新插件加载。",
  'The marketplace now pins {commit}; this reinstalls the commit you approved. Use "Update to {commit}" to move to it.':
    "插件市场现在固定在 {commit}；这会重新安装你批准过的提交。要切换过去，请使用“更新到 {commit}”。",
  "The model didn't answer. Try again.": "模型没有回应。请重试。",
